require 'uri'

# VC-62432: vcert encrypts the keystore password with a NaCl sealed box, but VSatellites with VSAT_HPKE keys need
# HPKE, so downloading a key generated by the service fails with HTTP 500. Scenarios that run into it skip instead
# of failing: on NGTS anywhere (the Go tests for service generated keys are skipped there for the same reason), and
# on CM SaaS only against a development stack (api-devNNN.qa.venafi.io), since the test tenant's VSatellite works.
VC_62432_NGTS = /failed to retrieve KeyStore on Palo Alto Networks Next-Gen Trust Security \(NGTS\), status: 500/
VC_62432_CMSAAS = /failed to retrieve KeyStore on CyberArk Certificate Manager, SaaS, status: 500/

# development_stack_url? reports whether a CM SaaS URL's host is a development stack's (*.qa.venafi.io). URLs may
# lack the scheme, as vcert accepts.
def development_stack_url?(url)
  url = url.to_s.strip
  return false if url.empty?
  url = "https://#{url}" unless url.match?(%r{\A[a-z][a-z0-9+.-]*://}i)
  host = URI.parse(url).host.to_s.downcase
  host.end_with?('.qa.venafi.io')
rescue URI::InvalidURIError
  false
end

AfterStep do
  output = begin
    last_command_started.output.to_s
  rescue StandardError
    # no command was started in this scenario, or it has not stopped
    next
  end
  development_stack = development_stack_url?(ENV['CLOUD_URL'])
  if output.match?(VC_62432_NGTS) || (development_stack && output.match?(VC_62432_CMSAAS))
    skip_this_scenario('VC-62432: the service generated key could not be downloaded (HTTP 500)')
  end
end
